module buffet_optimizer (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire discrete_valid,\n    input wire [9:0] discrete_weight,\n    input wire [15:0] discrete_t,\n    input wire [15:0] discrete_dt,\n    input wire cont1_valid,\n    input wire [15:0] cont1_t,\n    input wire [15:0] cont1_dt,\n    input wire cont2_valid,\n    input wire [15:0] cont2_t,\n    input wire [15:0] cont2_dt,\n    input wire [9:0] target_weight,\n    output reg [63:0] result,\n    output reg done,\n    output reg impossible\n);\n\n    // State definitions\n    localparam [2:0] IDLE             = 3'd0;\n    localparam [2:0] COMPUTE_DISCRETE = 3'd1;\n    localparam [2:0] COMPUTE_CONT     = 3'd2;\n    localparam [2:0] UPDATE_MAX       = 3'd3;\n    localparam [2:0] DONE_STATE       = 3'd4;\n\n    reg [2:0] current_state, next_state;\n\n    // Internal registers\n    reg [9:0] max_N;\n    reg [9:0] N_counter;\n    reg [9:0] remaining_weight;\n    reg [63:0] max_total;\n    reg [63:0] disc_tastiness;\n    reg [63:0] cont_tastiness;\n    reg [7:0] cycle_counter;\n\n    // Continuous dish calculation temporaries\n    reg [31:0] t1_div_dt1, t2_div_dt2;\n    reg [31:0] delta1, delta2;\n    reg [31:0] one_div_dt1, one_div_dt2;\n    reg [31:0] lambda_num, lambda_den;\n    reg [31:0] lambda;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Register initialization\n            current_state   <= IDLE;\n            done            <= 1'b0;\n            impossible      <= 1'b0;\n            result          <= 64'd0;\n            N_counter       <= 10'd0;\n            max_total       <= 64'd0;\n            disc_tastiness  <= 64'd0;\n            cont_tastiness  <= 64'd0;\n            remaining_weight<= 10'd0;\n            cycle_counter   <= 8'd0;\n        end else begin\n            cycle_counter <= cycle_counter + 8'd1;\n            case (current_state)\n                IDLE: begin\n                    done <= 1'b0;\n                    impossible <= 1'b0;\n                    if (start) begin\n                        if (!discrete_valid && !cont1_valid && !cont2_valid) begin\n                            impossible <= 1'b1;\n                            current_state <= DONE_STATE;\n                        end else begin\n                            N_counter <= 10'd0;\n                            max_total <= 64'd0;\n                            if (discrete_valid) begin\n                                if (discrete_weight == 10'd0) begin\n                                    max_N <= 10'd0;\n                                end else begin\n                                    max_N <= target_weight / discrete_weight;\n                                end\n                            end else begin\n                                max_N <= 10'd0;\n                            end\n                            current_state <= COMPUTE_DISCRETE;\n                        end\n                    end\n                end\n\n                COMPUTE_DISCRETE: begin\n                    if (N_counter <= max_N) begin\n                        // Discrete dish tastiness calculation\n                        disc_tastiness <= (N_counter * discrete_t) - ((discrete_dt * N_counter * (N_counter - 10'd1)) >>> 1);\n                        remaining_weight <= target_weight - (N_counter * discrete_weight);\n                        current_state <= COMPUTE_CONT;\n                    end else begin\n                        current_state <= DONE_STATE;\n                    end\n                end\n\n                COMPUTE_CONT: begin\n                    if (remaining_weight <= target_weight) begin\n                        // Single continuous dish logic\n                        if (cont1_valid && !cont2_valid && remaining_weight != 10'd0) begin\n                            cont_tastiness <= (cont1_t * remaining_weight) - ((cont1_dt * remaining_weight * remaining_weight) >>> 1);\n                        end else if (cont2_valid && !cont1_valid && remaining_weight != 10'd0) begin\n                            cont_tastiness <= (cont2_t * remaining_weight) - ((cont2_dt * remaining_weight * remaining_weight) >>> 1);\n                        end else if (cont1_valid && cont2_valid && remaining_weight != 10'd0) begin\n                            // Two continuous dish calculation (simplified)\n                            one_div_dt1 = (32'd1 << 16) / cont1_dt;\n                            one_div_dt2 = (32'd1 << 16) / cont2_dt;\n                            t1_div_dt1 = (cont1_t << 16) / cont1_dt;\n                            t2_div_dt2 = (cont2_t << 16) / cont2_dt;\n                            lambda_num = t1_div_dt1 + t2_div_dt2 - (remaining_weight << 16);\n                            lambda_den = one_div_dt1 + one_div_dt2;\n                            lambda = (lambda_den != 32'd0) ? (lambda_num << 16) / lambda_den : 32'd0;\n\n                            delta1 = (cont1_t << 16) - lambda;\n                            delta2 = (cont2_t << 16) - lambda;\n\n                            if (lambda <= (cont1_t << 16) && lambda <= (cont2_t << 16)) begin\n                                cont_tastiness <= ((delta1 * delta1) / cont1_dt + (delta2 * delta2) / cont2_dt) >> 17;\n                            end else begin\n                                // Degenerate case handling\n                                cont_tastiness <= 64'd0; // Placeholder for simplification\n                            end\n                        end else begin\n                            cont_tastiness <= 64'd0; // Invalid case\n                        end\n                    end\n                    current_state <= UPDATE_MAX;\n                end\n\n                UPDATE_MAX: begin\n                    if (cont_tastiness[63] == 1'b0) begin // Skip if negative\n                        if ((disc_tastiness + cont_tastiness) > max_total) begin\n                            max_total <= disc_tastiness + cont_tastiness;\n                        end\n                    end\n                    N_counter <= N_counter + 10'd1;\n                    current_state <= COMPUTE_DISCRETE;\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    if (cont_tastiness[63] || (max_total == 64'd0 && target_weight != 10'd0)) begin\n                        impossible <= 1'b1;\n                    end\n                    current_state <= IDLE;\n                end\n\n                default: current_state <= IDLE;\n            endcase\n\n            // Timeout protection\n            if (cycle_counter > 8'd200) begin\n                impossible <= 1'b1;\n                done <= 1'b1;\n                current_state <= IDLE;\n            end\n        end\n    end\n\nendmodule